import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"Stack three layers on the same contract","description":"","frontmatter":{},"headers":[],"relativePath":"en/cookbook/three-layer-stack.md","filePath":"en/cookbook/three-layer-stack.md"}'),n={name:"en/cookbook/three-layer-stack.md"};function i(r,e,c,l,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="stack-three-layers-on-the-same-contract" tabindex="-1">Stack three layers on the same contract <a class="header-anchor" href="#stack-three-layers-on-the-same-contract" aria-label="Permalink to &quot;Stack three layers on the same contract&quot;">​</a></h1><blockquote><p><a href="./three-layer-stack">🇬🇧 English</a> • <a href="./../../ja/cookbook/three-layer-stack">🇯🇵 日本語</a></p></blockquote><p>kiwa lets you run <strong>Foundry (<code>.t.sol</code>) + Hardhat (<code>.test.cjs</code>) + Playwright (<code>.spec.ts</code>)</strong> against a single Solidity contract. This recipe walks the same approach for three reference contracts so you can confirm the pattern is not specific to one example.</p><h2 id="when-to-choose-three-layers" tabindex="-1">When to choose three layers <a class="header-anchor" href="#when-to-choose-three-layers" aria-label="Permalink to &quot;When to choose three layers&quot;">​</a></h2><p>Use all three layers when one of the following is true.</p><ul><li>You want runner diversity (Foundry <code>vm.warp</code> / Hardhat <code>solidity-coverage</code> / Playwright on-chain assertion) to catch the same bug from different angles.</li><li>You want to keep a contract test (<code>forge test</code> + <code>npx hardhat test</code>) and a UX-level e2e test (<code>playwright test</code>) in lockstep with one Layer 1 spec (<code>/kiwa-design --layer contract</code> and <code>--layer e2e</code>).</li><li>You want to cover both the contract surface and the dApp surface in a single regression suite.</li></ul><p>If you only need contract correctness, run Foundry alone. If you only need UX, run Playwright alone. The three-layer stack pays off when you want all of the above to stay aligned.</p><h2 id="three-reference-contracts" tabindex="-1">Three reference contracts <a class="header-anchor" href="#three-reference-contracts" aria-label="Permalink to &quot;Three reference contracts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>Contract</th><th>Foundry lane</th><th>Hardhat lane</th><th>Playwright lane</th></tr></thead><tbody><tr><td><a href="./../../../tests/fixtures/mint-nft/"><code>tests/fixtures/mint-nft</code></a></td><td><code>MintNft.sol</code> (ERC721 + Enumerable + royalty)</td><td><code>contract-test/MintNft.t.sol</code> (27/27)</td><td><code>hardhat-test/MintNft.test.cjs</code> (24/24)</td><td><code>e2e-test/mint.spec.ts</code> (8/8)</td></tr><tr><td><a href="./../../../tests/fixtures/defi-swap/"><code>tests/fixtures/defi-swap</code></a></td><td><code>SimpleSwap.sol</code> + <code>Erc20.sol</code> (1:1 swap pool with slippage protection)</td><td><code>contract-test/SwapTokens.t.sol</code> (17/17)</td><td><code>hardhat-test/SwapTokens.test.cjs</code> (23/23)</td><td><code>e2e-test/swap.spec.ts</code> (7/7)</td></tr><tr><td><a href="./../../../tests/fixtures/nextjs-token-gating/"><code>tests/fixtures/nextjs-token-gating</code></a></td><td><code>GatedContent.sol</code> (NFT-gated access + timed grant)</td><td><code>contract-test/GatedContent.t.sol</code> (20/20)</td><td><code>hardhat-test/GatedContent.test.cjs</code> (23/23)</td><td><code>e2e-test/gating.spec.ts</code> (8/8)</td></tr></tbody></table><p>Run any lane directly from its fixture directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Foundry lane (any example)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/fixtures/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:foundry</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Hardhat lane (any example)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/fixtures/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:hardhat</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Playwright lane (any example)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/fixtures/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span></span></code></pre></div><p>The 9 entries (3 examples × 3 lanes) cover three contract shapes (NFT mint, AMM swap, gated content) to demonstrate that the stack is not tied to one specific contract pattern.</p><h2 id="why-all-three-lanes-pass-on-the-same-contract" tabindex="-1">Why all three lanes pass on the same contract <a class="header-anchor" href="#why-all-three-lanes-pass-on-the-same-contract" aria-label="Permalink to &quot;Why all three lanes pass on the same contract&quot;">​</a></h2><p>The shared Layer 1 spec (<code>tests/spec/contract/test-spec-&lt;name&gt;.md</code> and <code>tests/spec/e2e/test-spec-&lt;name&gt;.md</code>) is the single source of truth. Layer 2 skills read it and mechanically translate.</p><ul><li><code>/kiwa-forge</code> translates the spec&#39;s TC table into Foundry helpers (<code>vm.expectRevert</code>, <code>forge fuzz</code>, <code>vm.warp</code>).</li><li><code>/kiwa-hardhat</code> translates the same table into Hardhat helpers (<code>expect(...).to.be.reverted</code>, <code>fast-check</code>, <code>time.increaseTo</code>).</li><li><code>/kiwa-play</code> translates the spec&#39;s e2e TC table into Playwright + <code>@kiwa-lab/dapp</code> fixture helpers (<code>getByTestId</code>, <code>walletClient.signTypedData</code>).</li></ul><p>The viewpoint × runner mapping table in <a href="./../../../.claude/skills/kiwa-design/references/viewpoints-catalog"><code>viewpoints-catalog.md</code></a> lists each translation per viewpoint, so a contributor can predict what the generated test will look like before invoking Layer 2.</p><h2 id="how-to-add-a-fourth-contract-to-this-stack" tabindex="-1">How to add a fourth contract to this stack <a class="header-anchor" href="#how-to-add-a-fourth-contract-to-this-stack" aria-label="Permalink to &quot;How to add a fourth contract to this stack&quot;">​</a></h2><p>Pick any contract under <code>examples/&lt;name&gt;/contracts/</code>, then walk the skill chain in this order.</p><ol><li><code>/kiwa-design --layer contract --module &lt;name&gt; --input examples/&lt;name&gt;/contracts/&lt;Contract&gt;.sol</code></li><li><code>/kiwa-forge --module &lt;name&gt;</code> → <code>examples/&lt;name&gt;/test/&lt;Contract&gt;.t.sol</code></li><li><code>/kiwa-hardhat --module &lt;name&gt;</code> → <code>examples/&lt;name&gt;/hardhat-test/&lt;Contract&gt;.test.cjs</code></li><li><code>/kiwa-design --layer e2e --module &lt;name&gt; --input examples/&lt;name&gt;/app/page.tsx</code></li><li><code>/kiwa-play --module &lt;name&gt;</code> → <code>examples/&lt;name&gt;/tests/&lt;name&gt;.spec.ts</code></li></ol><p>If the contract uses time-dependent logic (vesting, voting deadlines), prefer Foundry for the contract lane — <code>vm.warp</code> is the simplest way to test boundary times. If the contract emits many events that the UI needs to react to, prefer Playwright for the e2e lane so you can assert against the UI directly via <code>getByTestId</code>.</p><p>For runner-specific limitations, the spec captures them under <a href="./../../../.claude/skills/kiwa-design/references/output-skeleton"><code>runner 差異</code></a> bullets so the contributor does not chase coverage on a branch that one runner cannot reach.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../../../tests/docs/skill-chain-tutorial"><code>tests/docs/skill-chain-tutorial.md</code></a> — Full skill-chain flow from spec to test</li><li><a href="./../../../tests/docs/run-contract-tests"><code>tests/docs/run-contract-tests.md</code></a> — Contract side procedure (Foundry + Hardhat)</li><li><a href="./../../../tests/docs/run-dapp-e2e-tests"><code>tests/docs/run-dapp-e2e-tests.md</code></a> — dApp e2e procedure (Playwright)</li><li><a href="./../../EXAMPLE-FIXTURES"><code>docs/EXAMPLE-FIXTURES.md</code></a> — Which examples have a completed fixture</li></ul>`,23)])])}const u=t(n,[["render",i]]);export{k as __pageData,u as default};
